1	import { HttpClient, HttpErrorResponse } from '@angular/common/http';
2	import { Component, Injectable, computed, inject, input, signal } from '@angular/core';
3	import { FigPipe } from '../../core/locale';
4	import { firstValueFrom } from 'rxjs';
5	import { Session } from '../../core/session';
6	import { AMOUNT, ClaimLogLine, ClaimStatus, statusAtEndOf } from '../claims/claims';
7	import { sumSkippingNa } from '../rates/rates';
8	import { SettingsStore } from '../settings/settings';
9	
10	export interface PeriodView {
11	  id: number;
12	  name: string;
13	  // Both inclusive (yyyy-mm-dd).
14	  from: string;
15	  to: string;
16	  // The most OPEN or PENDING claims a person may have in it (those due by a date in it); null for no cap.
17	  cap: number | null;
18	  // A closed period keeps the due-total fixed when it was closed; no claim due by a date in it can change.
19	  closed: boolean;
20	  // A soft-closed period keeps its due-total fixed the same way, but claims due by a date in it can still change.
21	  softClosed: boolean;
22	  closedTotal: string | null;
23	  // Each person's due-total fixed when it was closed or soft-closed, by person id; empty while it is open.
24	  closedPersonTotals: Record<string, string>;
25	  // Each person's carried figure fixed when it was closed or soft-closed, by person id; empty while it is open.
26	  closedPersonCarried: Record<string, string>;
27	  // Each person's opening balance for it, added to their carried figure, by person id; a person with none has no entry.
28	  personOpenings: Record<string, string>;
29	  // A locked period cannot be reopened until a steward unlocks it.
30	  locked: boolean;
31	}
32	
33	/**
34	 * A claim the live rules do not leave out (deferred or retired): its person, its due-by (which decides its period), the
35	 * figure it totals now (null for n/a), and its status and log, which decide whether it counted at the end of a period.
36	 */
37	export interface DatedFigure {
38	  personId: number;
39	  dueBy: string;
40	  figure: string | null;
41	  status: ClaimStatus;
42	  log: ClaimLogLine[];
43	}
44	
45	/** Whether a claim with the status counts: open, pending or settled. */
46	function countingStatus(status: ClaimStatus | null | undefined): boolean {
47	  return status === 'OPEN' || status === 'PENDING' || status === 'SETTLED';
48	}
49	
50	/** Whether the claim counted at the end of the day: its status then is open, pending or settled. */
51	function countedAtEndOf(f: DatedFigure, day: string): boolean {
52	  return countingStatus(statusAtEndOf(f, day));
53	}
54	
55	/** Whether the claim counts by its status now (open, pending or settled), whatever it was at the end of the day. */
56	function countedNow(f: DatedFigure): boolean {
57	  return countingStatus(f.status);
58	}
59	
60	/** How a period's due-total decides whether a claim counts: given the claim and the period's last day. */
61	export type PeriodCounting = (f: DatedFigure, lastDay: string) => boolean;
62	
63	const DATE = /^\d{4}-\d{2}-\d{2}$/;
64	
65	/**
66	 * The fiscal year the date falls in, named FY<yyyy> by the calendar year its first day falls in: fiscal years start on
67	 * the first of the start month (1 to 12).
68	 */
69	export function fiscalYearOf(date: string, startMonth: number): string {
70	  const year = Number(date.slice(0, 4));
71	  const month = Number(date.slice(5, 7));
72	  return `FY${month >= startMonth ? year : year - 1}`;
73	}
74	
75	/** The period whose dates contain the date; undefined when none does. */
76	export function periodOn(periods: readonly PeriodView[], date: string): PeriodView | undefined {
77	  return periods.find((p) => p.from <= date && date <= p.to);
78	}
79	
80	/** Whether a closed period contains the date. */
81	export function inClosedPeriod(periods: readonly PeriodView[], date: string): boolean {
82	  return periodOn(periods, date)?.closed ?? false;
83	}
84	
85	/**
86	 * The person's due-total for each period, by period id: a closed one's figure fixed for them when it was closed
87	 * (0.00 for a person added since), else the figures now of their claims due by a date in it that counted at the end of its
88	 * last day, skipping n/a.
89	 */
90	export function personPeriodDueTotals(
91	  periods: readonly PeriodView[],
92	  personId: number,
93	  figures: readonly DatedFigure[],
94	  counted: PeriodCounting = countedAtEndOf,
95	): Map<number, string> {
96	  const by = new Map<number, (string | null)[]>();
97	  for (const p of periods) by.set(p.id, []);
98	  for (const f of figures) {
99	    if (f.personId !== personId) continue;
100	    const p = periodOn(periods, f.dueBy);
101	    if (p && counted(f, p.to)) by.get(p.id)?.push(f.figure);
102	  }
103	  return new Map(
104	    periods.map((p) => [
105	      p.id,
106	      p.closed || p.softClosed ? (p.closedPersonTotals[personId] ?? '0.00') : sumSkippingNa(by.get(p.id) ?? []),
107	    ]),
108	  );
109	}
110	
111	/**
112	 * The person's carried figure for each period, by period id: a closed or soft-closed one's figure fixed for them when it
113	 * was closed (0.00 for a person added since), else the figures now of their claims belonging to a period that ends
114	 * before this one starts and still open or pending at the end of this one's last day, skipping n/a, plus their opening
115	 * balance for it.
116	 */
117	export function personPeriodCarried(
118	  periods: readonly PeriodView[],
119	  personId: number,
120	  figures: readonly DatedFigure[],
121	): Map<number, string> {
122	  const by = new Map<number, (string | null)[]>();
123	  for (const p of periods) by.set(p.id, [p.personOpenings[personId] ?? '0.00']);
124	  for (const f of figures) {
125	    if (f.personId !== personId) continue;
126	    const own = periodOn(periods, f.dueBy);
127	    if (!own) continue;
128	    for (const p of periods) {
129	      if (own.to >= p.from) continue;
130	      const status = statusAtEndOf(f, p.to);
131	      if (status === 'OPEN' || status === 'PENDING') by.get(p.id)?.push(f.figure);
132	    }
133	  }
134	  return new Map(
135	    periods.map((p) => [
136	      p.id,
137	      p.closed || p.softClosed ? (p.closedPersonCarried[personId] ?? '0.00') : sumSkippingNa(by.get(p.id) ?? []),
138	    ]),
139	  );
140	}
141	
142	/** Each period's due-total, by period id: the sum of the people's due-totals for it. */
143	export function periodDueTotals(
144	  periods: readonly PeriodView[],
145	  figures: readonly DatedFigure[],
146	  counted: PeriodCounting = countedAtEndOf,
147	): Map<number, string> {
148	  // everyone with a figure for some period: a counted claim, or one fixed when a period closed
149	  const people = new Set(figures.map((f) => f.personId));
150	  for (const p of periods) for (const id of Object.keys(p.closedPersonTotals)) people.add(Number(id));
151	  const each = [...people].map((id) => personPeriodDueTotals(periods, id, figures, counted));
152	  return new Map(periods.map((p) => [p.id, sumSkippingNa(each.map((m) => m.get(p.id) ?? null))]));
153	}
154	
155	/**
156	 * Each period's classic due-total, by period id: as periodDueTotals, but each claim counted by its status now (open,
