166	// The periods of the active sheet, by from-date.
167	@Injectable({ providedIn: 'root' })
168	export class PeriodStore {
169	  private readonly http = inject(HttpClient);
170	  private readonly session = inject(Session);
171	
172	  readonly list = signal<readonly PeriodView[]>([]);
173	
174	  /** Re-read the sheet's periods from the store. */
175	  async load(sheet: string): Promise<void> {
176	    this.list.set([]);
177	    const list = await firstValueFrom(this.http.get<PeriodView[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods`));
178	    if (this.session.sheetId() === sheet) this.list.set(list);
179	  }
180	
181	  async add(sheet: string, name: string, from: string, to: string, cap: number | null): Promise<void> {
182	    const p = await firstValueFrom(
183	      this.http.post<PeriodView>(`/api/sheets/${encodeURIComponent(sheet)}/periods`, { name, from, to, cap }),
184	    );
185	    this.put(sheet, p);
186	  }
187	
188	  /** Generate one period per month from the from-date's month to the to-date's; answers how many were made. */
189	  async generate(sheet: string, from: string, to: string): Promise<number> {
190	    const made = await firstValueFrom(
191	      this.http.post<PeriodView[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods/generate`, { from, to }),
192	    );
193	    for (const p of made) this.put(sheet, p);
194	    return made.length;
195	  }
196	
197	  /** Generate the fiscal year FY<year>'s twelve monthly periods as generate does; answers how many were made. */
198	  async generateFiscalYear(sheet: string, year: number): Promise<number> {
199	    const made = await firstValueFrom(
200	      this.http.post<PeriodView[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods/generate-fy`, { year }),
201	    );
202	    for (const p of made) this.put(sheet, p);
203	    return made.length;
204	  }
205	
206	  /**
207	   * Roll FY<year> over: generate FY<year + 1>'s periods and carry each person's open figure into its first period's
208	   * opening balances; answers how many periods were made.
209	   */
210	  async rollover(sheet: string, year: number): Promise<number> {
211	    const made = await firstValueFrom(
212	      this.http.post<PeriodView[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods/rollover`, { year }),
213	    );
214	    await this.load(sheet);
215	    return made.length;
216	  }
217	
218	  /** Undo the sheet's last rollover: its periods are removed and the opening balances it set taken back. */
219	  async undoRollover(sheet: string): Promise<void> {
220	    await firstValueFrom(this.http.post<void>(`/api/sheets/${encodeURIComponent(sheet)}/periods/rollover/undo`, {}));
221	    await this.load(sheet);
222	  }
223	
224	  /** Generate the calendar year's four quarterly periods, <yyyy>-Q1 to <yyyy>-Q4; answers how many were made. */
225	  async generateQuarters(sheet: string, year: number): Promise<number> {
226	    const made = await firstValueFrom(
227	      this.http.post<PeriodView[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods/generate-quarters`, { year }),
228	    );
229	    for (const p of made) this.put(sheet, p);
230	    return made.length;
231	  }
232	
233	  async close(sheet: string, id: number): Promise<void> {
234	    const p = await firstValueFrom(
235	      this.http.post<PeriodView>(`/api/sheets/${encodeURIComponent(sheet)}/periods/${id}/close`, null),
236	    );
237	    this.put(sheet, p);
238	  }
239	
240	  async softClose(sheet: string, id: number): Promise<void> {
241	    const p = await firstValueFrom(
242	      this.http.post<PeriodView>(`/api/sheets/${encodeURIComponent(sheet)}/periods/${id}/soft-close`, null),
243	    );
244	    this.put(sheet, p);
245	  }
246	
247	  async reopen(sheet: string, id: number): Promise<void> {
248	    const p = await firstValueFrom(
249	      this.http.post<PeriodView>(`/api/sheets/${encodeURIComponent(sheet)}/periods/${id}/reopen`, null),
250	    );
251	    this.put(sheet, p);
252	  }
253	
254	  /** Lock the period, or unlock it. */
255	  async setLocked(sheet: string, id: number, locked: boolean): Promise<void> {
256	    const p = await firstValueFrom(
257	      this.http.post<PeriodView>(
258	        `/api/sheets/${encodeURIComponent(sheet)}/periods/${id}/${locked ? 'lock' : 'unlock'}`,
259	        null,
260	      ),
261	    );
262	    this.put(sheet, p);
263	  }
264	
265	  /** Add each pasted line of name,period,amount to the opening balances, all or none; answers how many went through. */
266	  async importOpenings(sheet: string, text: string): Promise<number> {
267	    const done = await firstValueFrom(
268	      this.http.post<{ count: number }>(`/api/sheets/${encodeURIComponent(sheet)}/periods/openings`, { text }),
269	    );
270	    await this.load(sheet);
271	    return done.count;
272	  }
273	
274	  private put(sheet: string, p: PeriodView): void {
275	    if (this.session.sheetId() === sheet) {
276	      this.list.update((l) => [...l.filter((x) => x.id !== p.id), p].sort((a, b) => a.from.localeCompare(b.from)));
277	    }
278	  }
279	}
