690	  }
691	
692	  /** Undoes the last rollover; only the steward who made it, on the same sheet-today, while no claim is in its periods. */
693	  protected async undoRollover(): Promise<void> {
694	    if (this.rollingOver) return;
695	    this.rolloverMade.set(null);
696	    this.rolloverError.set(null);
697	    const sheet = this.session.sheetId();
698	    if (!sheet) return;
699	    this.rollingOver = true;
700	    try {
701	      await this.store.undoRollover(sheet);
702	    } catch (err) {
703	      if (this.session.sheetId() !== sheet) return;
704	      this.rolloverError.set(
705	        err instanceof HttpErrorResponse && err.status === 403
706	          ? 'Only the steward who rolled the year over may undo it.'
707	          : err instanceof HttpErrorResponse && err.status === 422
708	            ? 'That rollover cannot be undone: there is none, it was made on another day, or a claim is in its periods.'
709	            : 'Could not undo the rollover.',
710	      );
711	    } finally {
712	      this.rollingOver = false;
713	    }
714	  }
715	
716	  /** Generates the fiscal year's twelve monthly periods as generate does; shows how many were made. */
717	  protected async generateFiscalYear(e: Event): Promise<void> {
718	    e.preventDefault();
719	    if (this.generating) return;
720	    this.generated.set(null);
721	    this.genError.set(null);
722	    const sheet = this.session.sheetId();
723	    if (!sheet) return;
724	    const year = this.fyYear().trim();
725	    if (!/^\d{4}$/.test(year) || year === '0000' || year === '9999') {
726	      this.genError.set('Enter a fiscal year as yyyy.');
727	      return;
728	    }
729	    this.generating = true;
730	    try {
731	      const made = await this.store.generateFiscalYear(sheet, Number(year));
732	      if (this.session.sheetId() !== sheet) return;
733	      this.generated.set(made);
734	    } catch {
735	      this.genError.set('Could not generate that fiscal year\'s periods.');
736	    } finally {
737	      this.generating = false;
738	    }
739	  }
740	
741	  /** Generates the calendar year's four quarters as the period form would add them, leaving out any named or overlapped; shows how many were made. */
742	  protected async generateQuarters(e: Event): Promise<void> {
743	    e.preventDefault();
744	    if (this.generating) return;
745	    this.generated.set(null);
746	    this.genError.set(null);
747	    const sheet = this.session.sheetId();
748	    if (!sheet) return;
749	    const year = this.quarterYear().trim();
750	    if (!/^\d{4}$/.test(year) || year === '0000') {
751	      this.genError.set('Enter a year as yyyy.');
752	      return;
753	    }
754	    this.generating = true;
755	    try {
756	      const made = await this.store.generateQuarters(sheet, Number(year));
757	      if (this.session.sheetId() !== sheet) return;
758	      this.generated.set(made);
759	    } catch {
760	      this.genError.set('Could not generate that year\'s quarters.');
761	    } finally {
762	      this.generating = false;
763	    }
764	  }
765	
766	  protected async submit(e: Event): Promise<void> {
767	    e.preventDefault();
768	    if (this.submitting) return;
769	    this.error.set(null);
770	    const sheet = this.session.sheetId();
771	    if (!sheet) return;
772	    const name = this.name().trim();
773	    if (!name) {
774	      this.error.set('Enter a name.');
775	      return;
776	    }
777	    const from = this.from().trim() || (this.session.realToday() ?? '');
778	    const to = this.to().trim();
779	    if (!DATE.test(from) || !DATE.test(to)) {
780	      this.error.set('Enter a from and a to date as yyyy-mm-dd.');
781	      return;
782	    }
783	    if (to < from) {
784	      this.error.set('A period cannot end before it starts.');
785	      return;
786	    }
787	    const capText = this.cap().trim();
788	    if (capText && (!/^\d+$/.test(capText) || Number(capText) < 1 || Number(capText) > 1000000)) {
789	      this.error.set('Enter the cap as a whole number of at least 1, or leave it blank for none.');
790	      return;
791	    }
792	    const cap = capText ? Number(capText) : null;
793	    if (this.store.list().some((p) => p.name === name)) {
794	      this.error.set('That period name is already in use on this sheet.');
795	      return;
796	    }
797	    if (this.store.list().some((p) => p.from <= to && from <= p.to)) {
798	      this.error.set('That period overlaps another.');
799	      return;
800	    }
801	    this.submitting = true;
802	    try {
803	      await this.store.add(sheet, name, from, to, cap);
804	      this.name.set('');
805	      this.from.set('');
806	      this.to.set('');
807	      this.cap.set('');
808	    } catch (err) {
809	      this.error.set(
810	        err instanceof HttpErrorResponse && err.status === 409
811	          ? 'That period name is in use, or its dates overlap another period.'
812	          : 'Could not add that period.',
813	      );
814	    } finally {
815	      this.submitting = false;
816	    }
817	  }
